challenge_result.investigation_instruction:
{
  "plans": [
    {
      "hypothesis_id": "h1",
      "hypothesis_statement": "dns is the source of the UPF GTP drops and the P-CSCF INVITE spikes, as its container has unexpectedly exited and broken name resolution.",
      "primary_suspect_nf": "dns",
      "probes": [
        {
          "tool": "get_network_status",
          "args_hint": "Check the runtime state of the dns container.",
          "expected_if_hypothesis_holds": "The dns container is reported as exited or down.",
          "falsifying_observation": "The dns container is reported as running.",
          "conflates_with": []
        },
        {
          "tool": "measure_rtt",
          "args_hint": "container='pcscf', target_ip='172.22.0.15'",
          "expected_if_hypothesis_holds": "100% packet loss, confirming the dns container is completely unreachable.",
          "falsifying_observation": "0% packet loss, indicating the dns container network stack is still reachable and responding to ICMP.",
          "conflates_with": [
            "pcscf network interface failure",
            "docker bridge routing failure between pcscf and dns"
          ]
        },
        {
          "tool": "measure_rtt",
          "args_hint": "container='smf', target_ip='172.22.0.15'",
          "expected_if_hypothesis_holds": "100% packet loss, confirming the dns IP is globally unreachable across the deployment and isolating the failure to the dns container.",
          "falsifying_observation": "0% packet loss, meaning the dns container is reachable from the core network, proving the issue is an isolated pcscf routing failure rather than dns being down.",
          "conflates_with": []
        }
      ],
      "notes": "Using KB-authored liveness checks. The network status tool directly observes the container exit, while the paired measure_rtt probes confirm global unreachability of the DNS IP to rule out isolated routing faults."
    }
  ]
}
